import{_ as e,c as r,o as a,ae as d}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse(`{"title":"Merge Cart","description":"","frontmatter":{"outline":false,"examples":[{"id":"merge-cart","title":"Merge Guest Cart into Customer Cart","description":"After a guest logs in, merge the guest cart's items into the authenticated customer's cart. Send the customer's Bearer token and the guest cart's id.","request":"POST /api/shop/merge-carts\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 867|DlQxl04kMnUjSpduZpd2gaVWX8oi3vvGY3RZn4pE\\n\\n{\\n  \\"cartId\\": 6884\\n}\\n","response":"{\\n  \\"id\\": 6885,\\n  \\"cartToken\\": \\"6885\\",\\n  \\"customerId\\": 1533,\\n  \\"channelId\\": 1,\\n  \\"itemsCount\\": 1,\\n  \\"itemsQty\\": 1,\\n  \\"items\\": [\\n    {\\n      \\"id\\": 7763,\\n      \\"cartId\\": 6885,\\n      \\"productId\\": 1,\\n      \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n      \\"quantity\\": 1,\\n      \\"price\\": 100,\\n      \\"total\\": 100,\\n      \\"type\\": \\"simple\\",\\n      \\"formattedPrice\\": \\"$100.00\\",\\n      \\"formattedTotal\\": \\"$100.00\\"\\n    }\\n  ],\\n  \\"subtotal\\": 100,\\n  \\"grandTotal\\": 100,\\n  \\"taxAmount\\": 0,\\n  \\"discountAmount\\": 0,\\n  \\"couponCode\\": null,\\n  \\"formattedSubtotal\\": \\"$100.00\\",\\n  \\"formattedGrandTotal\\": \\"$100.00\\",\\n  \\"success\\": true,\\n  \\"message\\": \\"Cart merged successfully.\\"\\n}\\n","commonErrors":[{"error":"401 Unauthorized","cause":"No customer Bearer token — merge requires an authenticated customer","solution":"Log the customer in first and send the customer token in the Authorization header"},{"error":"404 Not Found","cause":"The guest cart id does not exist","solution":"Pass the id of a valid, active guest cart"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/merge-cart.md","filePath":"api/rest-api/shop/cart/merge-cart.md"}`),o={name:"api/rest-api/shop/cart/merge-cart.md"};function s(n,t,i,c,l,h){return a(),r("div",null,t[0]||(t[0]=[d(`<h1 id="merge-cart" tabindex="-1">Merge Cart <a class="header-anchor" href="#merge-cart" aria-label="Permalink to &quot;Merge Cart&quot;">​</a></h1><p>Merge a <strong>guest cart</strong> into the <strong>authenticated customer&#39;s cart</strong>. This is used when a shopper adds items to a cart as a guest and then logs in — the guest cart&#39;s items are moved into the customer&#39;s own cart so nothing is lost.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/merge-carts</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The <strong>customer</strong> Bearer token (from customer login) — not the cart token</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;cartId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6884</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>cartId</code></td><td>integer</td><td>Yes</td><td>The id of the guest cart to merge into the customer cart</td></tr></tbody></table><h2 id="how-the-merge-works" tabindex="-1">How the merge works <a class="header-anchor" href="#how-the-merge-works" aria-label="Permalink to &quot;How the merge works&quot;">​</a></h2><ol><li><strong>Auth is required</strong> — the request must carry a customer Bearer token. A guest (no token) is rejected with <code>401</code>.</li><li><strong>The guest cart is looked up by <code>cartId</code></strong> — an unknown id returns <code>404</code>.</li><li>The items are merged into the customer&#39;s <strong>active</strong> cart (one is created if the customer has none): <ul><li>An item already in the customer cart with the <strong>same product and type</strong> has its <strong>quantities added together</strong>.</li><li>Any other item is <strong>copied</strong> into the customer cart (a configurable product&#39;s selected-variant child is copied too).</li></ul></li><li>The <strong>guest cart is deactivated</strong> after the merge.</li><li>Invalid items are pruned (a deleted product, or a configurable item missing its variant), then <strong>totals are recalculated</strong>.</li><li>The response is the full, up-to-date <strong>customer cart</strong>.</li></ol><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>The merged (customer) cart id</td></tr><tr><td><code>cartToken</code></td><td>string</td><td>Cart token identifier</td></tr><tr><td><code>customerId</code></td><td>integer</td><td>Owner customer id</td></tr><tr><td><code>channelId</code></td><td>integer</td><td>Sales channel id</td></tr><tr><td><code>itemsCount</code></td><td>integer</td><td>Distinct item count</td></tr><tr><td><code>itemsQty</code></td><td>integer</td><td>Total quantity across items</td></tr><tr><td><code>items</code></td><td>array</td><td>The merged line items</td></tr><tr><td><code>subtotal</code></td><td>decimal</td><td>Subtotal before tax and discount</td></tr><tr><td><code>grandTotal</code></td><td>decimal</td><td>Final total</td></tr><tr><td><code>taxAmount</code></td><td>decimal</td><td>Tax total</td></tr><tr><td><code>discountAmount</code></td><td>decimal</td><td>Discount total</td></tr><tr><td><code>couponCode</code></td><td>string | null</td><td>Applied coupon, if any</td></tr><tr><td><code>formattedSubtotal</code></td><td>string</td><td>Subtotal with currency symbol</td></tr><tr><td><code>formattedGrandTotal</code></td><td>string</td><td>Grand total with currency symbol</td></tr><tr><td><code>success</code></td><td>boolean</td><td>Whether the merge succeeded</td></tr><tr><td><code>message</code></td><td>string</td><td>Result message</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Send the <strong>customer</strong> token, not the guest cart token — the guest cart is identified by the <code>cartId</code> in the body.</li><li>After a successful merge the guest cart is inactive; continue with the returned customer cart through checkout.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/create-cart.html">Create Cart</a> — obtain the cart token every other cart call needs</li><li><a href="/api/rest-api/shop/cart/get-cart.html">Get Cart</a> — read the current items and recalculated totals</li><li><a href="/api/workflows/shop/cart.html">Cart workflow</a> — the guest-to-customer cart flow end to end</li></ul>`,17)]))}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
